/**
 * The line every report file carries (ADR CM-0021 §2, `modules/11`
 * recommendation 9): who generated it and when, in the Company's time
 * zone, as "Generated by Asha Rao on 16 Oct 2026, 14:05". PDFs print it
 * in the footer of every page; Excel files under the header block.
 */

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

const FALLBACK_ZONE = "Asia/Kolkata";

function partsIn(at: Date, timeZone: string) {
  const format = new Intl.DateTimeFormat("en-GB", {
    timeZone,
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  });
  const parts = format.formatToParts(at);
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((item) => item.type === type)?.value ?? "";
  return {
    day: String(Number(part("day"))),
    month: MONTHS[Number(part("month")) - 1] ?? "",
    year: part("year"),
    hour: part("hour").padStart(2, "0"),
    minute: part("minute").padStart(2, "0"),
  };
}

/** `16 Oct 2026, 14:05` in `timeZone` (India when the zone is not valid). */
export function generatedAtText(at: Date, timeZone: string): string {
  let parts;
  try {
    parts = partsIn(at, timeZone);
  } catch {
    parts = partsIn(at, FALLBACK_ZONE);
  }
  return `${parts.day} ${parts.month} ${parts.year}, ${parts.hour}:${parts.minute}`;
}

/**
 * "Generated by Asha Rao on 16 Oct 2026, 14:05"; without a name (a
 * requester no longer in the Company) "Generated on 16 Oct 2026, 14:05".
 */
export function generatedByLine(
  name: string | null,
  at: Date,
  timeZone: string,
): string {
  const when = generatedAtText(at, timeZone);
  const who = name?.trim() ?? "";
  return who === "" ? `Generated on ${when}` : `Generated by ${who} on ${when}`;
}
